{
  "name": "@2api-store/activate",
  "version": "0.9.2",
  "description": "TokenShop CLI 一键激活：配置本地 codex/claude/gemini/grok/opencode 指向 2api.store 中转（彩色输出 + 自动安装 CLI）",
  "type": "module",
  "bin": {
    "activate": "./dist/activate.mjs"
  },
  "main": "./dist/activate.mjs",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "check": "node --check activate.mjs && for f in lib/*.mjs; do node --check \"$f\" || exit 1; done",
    "build": "node build.mjs",
    "prepublishOnly": "npm run check && npm run build",
    "smoke": "node test/smoke.mjs"
  },
  "files": [
    "dist/",
    "README.md"
  ],
  "keywords": [
    "cli",
    "activate",
    "2api",
    "tokenshop",
    "codex",
    "claude",
    "gemini",
    "grok",
    "opencode"
  ],
  "author": "TokenShop",
  "dependencies": {
    "@inquirer/prompts": "^7.0.0",
    "chalk": "^5.4.0",
    "fflate": "^0.8.3"
  },
  "devDependencies": {
    "javascript-obfuscator": "^4.1.0",
    "terser": "^5.31.0"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  }
}
